return
= LittlerootTown_MaysHouse_1F_EventScript_MayGoUpstairs0
applymovement LOCALID_PLAYER LittlerootTown_MaysHouse_1F_Movement_PlayerWatchMayExit0
applymovement LOCALID_RIVALS_HOUSE_1F_RIVAL LittlerootTown_MaysHouse_1F_Movement_MayGoUpstairs0
waitmovement 0
return
= LittlerootTown_MaysHouse_1F_EventScript_MayApproachPlayer2
applymovement LOCALID_RIVALS_HOUSE_1F_RIVAL LittlerootTown_MaysHouse_1F_Movement_MayApproachPlayer2
waitmovement 0
return
= LittlerootTown_MaysHouse_1F_EventScript_MayApproachPlayer1
applymovement LOCALID_RIVALS_HOUSE_1F_RIVAL LittlerootTown_MaysHouse_1F_Movement_MayApproachPlayer1
waitmovement 0
return
= LittlerootTown_MaysHouse_1F_EventScript_MayApproachPlayer0
applymovement LOCALID_RIVALS_HOUSE_1F_RIVAL LittlerootTown_MaysHouse_1F_Movement_MayApproachPlayer0
waitmovement 0
return
= LittlerootTown_MaysHouse_1F_EventScript_PlayerFaceMay
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterDown
waitmovement 0
return
= LittlerootTown_MaysHouse_1F_EventScript_MeetRival1
lockall
setvar VAR_0x8008 1
goto LittlerootTown_MaysHouse_1F_EventScript_MeetRival
end
= LittlerootTown_MaysHouse_1F_EventScript_MeetRival0
lockall
setvar VAR_0x8008 0
goto LittlerootTown_MaysHouse_1F_EventScript_MeetRival
end
= LittlerootTown_MaysHouse_1F_EventScript_GoSeeRoom
lockall
setvar VAR_0x8004 LOCALID_PLAYERS_HOUSE_1F_MOM
setvar VAR_0x8005 FEMALE
applymovement VAR_0x8004 Common_Movement_WalkInPlaceFasterRight
waitmovement 0
goto PlayersHouse_1F_EventScript_MomGoSeeRoom
end
= PlayersHouse_1F_EventScript_MomGoSeeRoom
msgbox	MOM: Na, PLAYER?Hast du keine Lust, dir dein eigenes Zimmer anzusehen?
closemessage
applymovement VAR_0x8004 Common_Movement_WalkInPlaceFasterUp
applymovement LOCALID_PLAYER PlayersHouse_1F_Movement_MovePlayerAwayFromDoor
waitmovement 0
releaseall
end
= RivalsHouse_1F_EventScript_RivalSibling
lock
faceplayer
special GetPlayerBigGuyGirlString
msgbox	Hi, Nachbar!Hast du schon dein eigenes POKéMON?
release
end
= RivalsHouse_1F_EventScript_RivalMom
lock
faceplayer
goto_if_set FLAG_DEFEATED_RIVAL_ROUTE103 RivalsHouse_1F_EventScript_GoHomeEverySoOften
goto_if_set FLAG_SYS_POKEMON_GET RivalsHouse_1F_EventScript_RivalIsOnRoute103
goto_if_eq VAR_LITTLEROOT_RIVAL_STATE 3 RivalsHouse_1F_EventScript_RivalTooBusy
special GetRivalSonDaughterString
msgbox	Ganz der Vater, dieses Kind.Mein Mann ist genauso wild auf POKéMON wie unser Kind.Wenn er nicht in seinem LABOR ist, dann wühlt er wahrscheinlich irgendwo im hohen Gras herum.
release
end
= RivalsHouse_1F_EventScript_RivalTooBusy
msgbox	Dieser RIVAL!Ich schätze, unser Kind ist mit POKéMON zu beschäftigt, um zu merken, dass du zu Besuch gekommen bist, PLAYER.
release
end
= RivalsHouse_1F_EventScript_RivalIsOnRoute103
msgbox	Oh, RIVAL ist vor Kurzem los, Richtung ROUTE 103.Ganz der Vater, dieses Kind. RIVAL hält es einfach nicht ruhig zu Hause aus.
release
end
= RivalsHouse_1F_EventScript_GoHomeEverySoOften
msgbox	Ich finde es wunderbar, wenn Menschen mit POKéMON auf Reisen gehen.Aber du solltest ab und zu nach Hause kommen, damit deine Mutter weiß, dass es dir gut geht.Sie sagt es vielleicht nicht, aber ich bin sicher, sie macht sich Sorgen um dich, PLAYER.
release
end
= PlayersHouse_1F_EventScript_Vigoroth2
lock
faceplayer
waitse
playmoncry SPECIES_VIGOROTH CRY_MODE_NORMAL
msgbox	Huggoh, uggo uggo…
waitmoncry
release
end
= PlayersHouse_1F_EventScript_Vigoroth1
lock
faceplayer
waitse
playmoncry SPECIES_VIGOROTH CRY_MODE_NORMAL
msgbox	Fugiiiiih!
waitmoncry
release
end
= PlayersHouse_1F_EventScript_Mom
lock
faceplayer
goto_if_eq VAR_LITTLEROOT_HOUSES_STATE_MAY 4 PlayersHouse_1F_EventScript_DontPushYourselfTooHard
goto_if_eq VAR_LITTLEROOT_HOUSES_STATE_BRENDAN 4 PlayersHouse_1F_EventScript_DontPushYourselfTooHard
goto_if_set FLAG_HAS_MATCH_CALL PlayersHouse_1F_EventScript_TryRegisterMom
goto_if_set FLAG_RESCUED_BIRCH PlayersHouse_1F_EventScript_MomHealsParty
goto_if_eq VAR_TEMP_1 1 PlayersHouse_1F_EventScript_SeeYouHoney
goto_if_eq VAR_LITTLEROOT_INTRO_STATE 7 PlayersHouse_1F_EventScript_DidYouMeetProfBirch
msgbox	MOM: Siehst du, PLAYER? Ist es hier drin nicht auch schön?
release
end
= PlayersHouse_1F_EventScript_DidYouMeetProfBirch
msgbox	MOM: Hast du dich schon bei PROF. BIRCH vorgestellt?
release
end
= PlayersHouse_1F_EventScript_SeeYouHoney
msgbox	MOM: Bis später, Schatz!
release
end
= PlayersHouse_1F_EventScript_MomHealsParty
msgbox	MOM: Wie geht's dir, PLAYER? Du siehst etwas müde aus.Ich glaube, du solltest dich ein bisschen ausruhen.
goto PlayersHouse_1F_EventScript_HealParty
end
= PlayersHouse_1F_EventScript_HealParty
closemessage
call Common_EventScript_OutOfCenterPartyHeal
incrementgamestat GAME_STAT_RESTED_AT_HOME
msgbox	MOM: Pass auf dich auf, Schatz!
release
end
= PlayersHouse_1F_EventScript_TryRegisterMom
goto_if_set FLAG_ENABLE_MOM_MATCH_CALL PlayersHouse_1F_EventScript_CheckGiveAmuletCoin
msgbox	MOM: Was ist das denn, Schatz? Ein POKéNAV? Hat dir das jemand von DEVON gegeben?Sag mal, Schatz, wie wär's, wenn du deine Mom registrierst?… … …
closemessage
delay 30
playfanfare MUS_REGISTER_MATCH_CALL
msgbox	MOM wurde im POKéNAV registriert.
waitfanfare
closemessage
delay 30
setflag FLAG_ENABLE_MOM_MATCH_CALL
release
end
= PlayersHouse_1F_EventScript_CheckGiveAmuletCoin
goto_if_set FLAG_BADGE05_GET PlayersHouse_1F_EventScript_TryGiveAmuletCoin
goto PlayersHouse_1F_EventScript_MomHealsParty
= PlayersHouse_1F_EventScript_TryGiveAmuletCoin
goto_if_set FLAG_RECEIVED_AMULET_COIN PlayersHouse_1F_EventScript_MomHealsParty
msgbox	MOM: Oh? Hat DAD dir dieses BADGE gegeben?Dann gibt's jetzt auch noch was von deiner MOM!
giveitem ITEM_AMULET_COIN
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
msgbox	Überanstreng dich nicht, Schatz. Du kannst jederzeit nach Hause kommen.Los, gib dein Bestes!
setflag FLAG_RECEIVED_AMULET_COIN
release
end
= PlayersHouse_1F_EventScript_DontPushYourselfTooHard
msgbox	Überanstreng dich nicht, Schatz. Du kannst jederzeit nach Hause kommen.Los, gib dein Bestes!
release
end

